import 'dart:async';
import '../../../../data/pronunciation_models.dart';
import '../../../../data/pronunciation_repository.dart';
import '../../pronunciation_highlight.dart';

// PronunciationPlaybackService handles pronunciation audio playback and highlight coordination
class PronunciationPlaybackService {
  final Stream<Duration> pronunciationPosition;
  final Future<void> Function(String url) playAudio;
  final Future<void> Function(String url) playBreakdown;

  final _highlightPartsController =
      StreamController<List<PronunciationHighlightPart>?>.broadcast();
  final _activePartIndexController = StreamController<int?>.broadcast();
  final _playbackCompleteController = StreamController<void>.broadcast();

  Stream<List<PronunciationHighlightPart>?> get highlightPartsStream =>
      _highlightPartsController.stream;
  Stream<int?> get activePartIndexStream => _activePartIndexController.stream;
  Stream<void> get playbackCompleteStream => _playbackCompleteController.stream;

  PronunciationPlaybackService({
    required this.pronunciationPosition,
    required this.playAudio,
    required this.playBreakdown,
  });

  Future<void> playWord(
    String word,
    PronunciationRepository repository,
    String bookId,
  ) async {
    final manifest = await repository.fetchManifest(bookId);
    final pronunciation = manifest[word];

    if (pronunciation == null || !pronunciation.hasAudio) {
      _playbackCompleteController.add(null);
      return;
    }

    final parts = _buildHighlightParts(pronunciation);
    _highlightPartsController.add(parts);

    if (pronunciation.includesBreakdown && pronunciation.breakdownUrl != null) {
      await _playBreakdownAudio(pronunciation);
    } else if (pronunciation.fullWordUrl != null) {
      await playAudio(pronunciation.fullWordUrl!);
    }

    _playbackCompleteController.add(null);
  }

  List<PronunciationHighlightPart>? _buildHighlightParts(
    WordPronunciation pronunciation,
  ) {
    if (!pronunciation.includesBreakdown) return null;

    final segments = pronunciation.breakdownSegments;
    if (segments.isEmpty) return null;

    return segments.asMap().entries.map((entry) {
      final i = entry.key;
      final seg = entry.value;
      final label = i < pronunciation.syllables.length
          ? pronunciation.syllables[i]
          : seg.chunk;
      return PronunciationHighlightPart(label: label, segmentIndex: i);
    }).toList();
  }

  Future<void> _playBreakdownAudio(WordPronunciation pronunciation) async {
    final segments = pronunciation.breakdownSegments;
    StreamSubscription<Duration>? sub;

    final completer = Completer<void>();
    int currentSegIndex = 0;

    sub = pronunciationPosition.listen((pos) {
      final ms = pos.inMilliseconds;
      // Find which segment is active
      for (int i = 0; i < segments.length; i++) {
        if (ms >= segments[i].startMs && ms < segments[i].endMs) {
          if (i != currentSegIndex) {
            currentSegIndex = i;
            _activePartIndexController.add(i);
          }
          break;
        }
      }
    });

    await playBreakdown(pronunciation.breakdownUrl!);
    await sub.cancel();
    completer.complete();

    // Signal reset after breakdown
    _highlightPartsController.add(null);
    _activePartIndexController.add(null);

    // Play full word
    if (pronunciation.fullWordUrl != null) {
      await playAudio(pronunciation.fullWordUrl!);
    }
  }

  void dispose() {
    _highlightPartsController.close();
    _activePartIndexController.close();
    _playbackCompleteController.close();
  }
}

